        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if spy_bar is not None:
            previous_close = self.spy_previous_close
            previous_sma = self.spy_previous_sma

            self.spy_previous_close = float(spy_bar.Close)
            self.spy_previous_sma = float(self.spy_sma.Current.Value)

            spy_previous_close_for_signal = previous_close
            spy_previous_sma_for_signal = previous_sma
        else:
            spy_previous_close_for_signal = None
            spy_previous_sma_for_signal = None

        if aapl_bar is not None:
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif float(aapl_bar.Close) < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = float(aapl_bar.Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(spy_bar.Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        spy_crosses_below = (
            spy_previous_close_for_signal is not None
            and spy_previous_sma_for_signal is not None
            and spy_previous_close_for_signal <= spy_previous_sma_for_signal
            and spy_close < spy_sma
        )

        spy_crosses_above = (
            spy_previous_close_for_signal is not None
            and spy_previous_sma_for_signal is not None
            and spy_previous_close_for_signal <= spy_previous_sma_for_signal
            and spy_close > spy_sma
        )

        # Sell rules are evaluated before buy rules.
        if self.spy_lot > 0 and not self.HasPendingOrder("SPY"):
            if spy_crosses_below:
                self.SubmitSell("SPY", self.spy_lot)

        if self.aapl_lot > 0 and not self.HasPendingOrder("AAPL"):
            if aapl_rsi > 60:
                self.SubmitSell("AAPL", self.aapl_lot)

        # Buy rules.
        if self.spy_lot == 0 and not self.HasPendingOrder("SPY"):
            if spy_crosses_above:
                portfolio_value = float(self.Portfolio.TotalPortfolioValue)
                quantity = int((portfolio_value * 0.40) // spy_close)

                if quantity > 0:
                    self.SubmitBuy("SPY", quantity)

        if self.aapl_lot == 0 and not self.HasPendingOrder("AAPL"):
            if self.aapl_red_streak >= 1:
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= 20000:
                    quantity = int(20000 // float(aapl_bar.Close))

                    if quantity > 0:
                        self.SubmitBuy("AAPL", quantity)

    def HasPendingOrder(self, ticker):
        return ticker in self.pending_orders

    def SubmitBuy(self, ticker, quantity):
        symbol = self.Symbol(ticker)
        ticket = self.MarketOrder(symbol, quantity)

        if ticket is not None and ticket.OrderId > 0:
            self.pending_orders[ticker] = ("buy", ticket.OrderId)

    def SubmitSell(self, ticker, quantity):
        symbol = self.Symbol(ticker)
        ticket = self.MarketOrder(symbol, -quantity)

        if ticket is not None and ticket.OrderId > 0:
            self.pending_orders[ticker] = ("sell", ticket.OrderId)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        matching_ticker = None
        action = None

        for ticker, pending in self.pending_orders.items():
            if pending[1] == order_id:
                matching_ticker = ticker
                action = pending[0]
                break

        if matching_ticker is None:
            return

        if order_event.Status == OrderStatus.Filled:
            fill_quantity = int(order_event.FillQuantity)

            if matching_ticker == "SPY":
                self.spy_lot += fill_quantity
                self.spy_lot = max(0, self.spy_lot)
            elif matching_ticker == "AAPL":
                self.aapl_lot += fill_quantity
                self.aapl_lot = max(0, self.aapl_lot)

            del self.pending_orders[matching_ticker]

        elif order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ]:
            if order_event.Status != OrderStatus.PartiallyFilled:
                del self.pending_orders[matching_ticker]
